import numpy as npfrom scipy.stats import geninvgaussrng = np.random.default_rng(seed=123)def sample_gig(lam, chi, psi, rng):    b = np.sqrt(chi * psi)    scale = np.sqrt(chi / psi)    return scale * geninvgauss.rvs(        lam, b, random_state=rng    )def sample_inverse_gamma(alpha, beta, rng):    gamma_tilde = rng.gamma(shape=alpha, scale=1.0 / beta)    if gamma_tilde <= 0.0:        print(gamma_tilde)        print(alpha)        print(beta)    return 1.0 / gamma_tildedef sample_efficient_beta(phi,D,alpha,rng):    n = phi.shape[0]    u = rng.multivariate_normal(np.zeros(D.shape[0]), D)    delta = rng.standard_normal(n)    v = phi@u+delta    matrix = phi@D@phi.T+np.eye(n)    w = np.linalg.solve(matrix,alpha-v)    theta = u+D@phi.T@w    return thetadef sample_psi(phi, tau, beta, sigma, rng):    mu = sigma * phi * tau / np.abs(beta)    psi_inv = rng.wald(mean=mu, scale=1.0)    return 1.0 / psi_invdef gibbs_sampler(X, y, n_iter, a, a1, b1, rng):    n, p = X.shape    # Initialise parameters    sigma2 = sample_inverse_gamma(a1, b1, rng)    phi = rng.dirichlet(np.full(p, a))    tau = rng.gamma(shape=p * a, scale=2.0)    psi = rng.exponential(scale=2.0, size=p)    S = psi * phi**2 * tau**2    S_1 = np.reciprocal(S)    beta = rng.normal(0.0, np.sqrt(sigma2 * S))    # Store posterior samples    beta_samples = np.empty((n_iter, p))    sigma2_samples = np.empty(n_iter)    psi_samples = np.empty((n_iter, p))    phi_samples = np.empty((n_iter, p))    tau_samples = np.empty(n_iter)    for iteration in range(n_iter):        #sample sigma        residual = y-X@beta        quad_1 = residual.T@residual        term_1 = np.sum(beta**2 / S)        sigma2 = sample_inverse_gamma(a1+(n+p)*0.5,b1+0.5*(quad_1+term_1),rng)                #sample beta        sigma = np.sqrt(sigma2)        beta = sample_efficient_beta(X/sigma,np.diag(S_1),y/sigma,rng)                #sample psi        for j in range(0,p):            psi_tilde_j = geninvgauss.rvs(sigma*tau*phi[j]/beta[j],1,random_state=rng)            psi[j] = np.reciprocal(psi_tilde_j)                #sample tau        tau = sample_gig(p*(a-1),1,(2/sigma)*np.sum(np.divide(np.abs(beta),phi)),rng)                #sample phi        T = np.zeros(p)        for j in range(p):            T[j] = sample_gig(a-1,2,(2/sigma)*np.abs(beta[j]))        for j in range(p):            phi[j] = T[j]/np.sum(T[:j])                                return {        "beta": beta_samples,        "sigma2": sigma2_samples,        "psi": psi_samples,        "phi": phi_samples,        "tau": tau_samples,    }# Generate synthetic regression datarng_data = np.random.default_rng(seed=42)n, p = 100, 20X = rng_data.normal(size=(n, p))X = (X - X.mean(axis=0)) / X.std(axis=0, ddof=1)# True sparse regression coefficientsbeta_true = np.zeros(p)beta_true[[1, 4, 9]] = [1.0, -1.5, 1.0]# Generate response with Gaussian noisey = X @ beta_true + rng_data.normal(0, 1, size=n)y = y-y.mean()# Run the Gibbs samplerrng = np.random.default_rng(seed=145623)samples = gibbs_sampler(    X=X,    y=y,    n_iter=5000,    a=.01,    a1=0.01,    b1=0.01,    rng=rng,)# Compare true coefficients with posterior meansbeta_mean = samples["beta"].mean(axis=0)print("True coefficients:    ", beta_true)print("Posterior mean:        ", np.round(beta_mean, 2))print("X shape:", X.shape)print("y shape:", y.shape)